//! Offline license issuance tool for StudioCut AI.
//!
//! The application verifies offline Ed25519 licenses (see
//! `studiocut_ai::license`), but it cannot issue them. This tool mints
//! licenses that verify against the same path: the payload format and
//! the signature encoding are reused from the library
//! (`license::sign_for_test` / `license::verify_with_key`), so issuance
//! and verification cannot drift apart.
//!
//! The private signing key is generated by this tool and never hardcoded
//! in the repository. Keep it offline and never commit it.
//!
//! ```text
//! # Generate a new vendor keypair (Linux/macOS read /dev/urandom;
//! # on Windows pass --seed with 32 random bytes, e.g. from
//! # `openssl rand -hex 32`).
//! license-tool generate-key [--seed <64 hex chars>]
//!
//! # Issue a license bound to one machine fingerprint (shown in the
//! # application under Settings > License).
//! license-tool issue --seed <hex or base64 seed> --name "Jane Doe" \
//!   --email jane@example.com --fingerprint <32 hex chars> \
//!   [--expires never | <unix seconds>]
//!
//! # Verify a license against a public key (hex).
//! license-tool verify --license <license text> \
//!   --fingerprint <32 hex chars> --public-key <64 hex chars>
//!
//! # Print this machine's fingerprint (for testing).
//! license-tool fingerprint
//! ```
//!
//! After `generate-key`, paste the printed public key into
//! `LICENSE_PUBLIC_KEY` in `src-tauri/src/license.rs` and rebuild before
//! issuing licenses with the new key. Licenses signed with a previous
//! key stop verifying after the public key is replaced, so plan key
//! rotation before any public release.

use base64::Engine;
use ed25519_dalek::{SigningKey, VerifyingKey, PUBLIC_KEY_LENGTH, SECRET_KEY_LENGTH};
use std::{
    process::ExitCode,
    time::{SystemTime, UNIX_EPOCH},
};
use studiocut_ai::license;

const PAYLOAD_PREFIX: &str = "STUDIOCUT-LICENSE-V1";

fn hex_encode(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn hex_decode(text: &str) -> Result<Vec<u8>, String> {
    let text = text.trim();
    if text.is_empty() || text.len() % 2 != 0 || !text.chars().all(|c| c.is_ascii_hexdigit()) {
        return Err("Expected even-length hexadecimal".into());
    }
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).map_err(|_| "Invalid hexadecimal".into()))
        .collect()
}

/// A 32-byte Ed25519 seed, given as 64 hex characters or base64.
fn parse_seed(text: &str) -> Result<[u8; SECRET_KEY_LENGTH], String> {
    let trimmed = text.trim();
    let bytes = if trimmed.len() == SECRET_KEY_LENGTH * 2
        && trimmed.chars().all(|c| c.is_ascii_hexdigit())
    {
        hex_decode(trimmed)?
    } else {
        base64::engine::general_purpose::STANDARD
            .decode(trimmed)
            .or_else(|_| base64::engine::general_purpose::URL_SAFE_NO_PAD.decode(trimmed))
            .map_err(|_| "Seed must be 64 hex characters or base64".to_string())?
    };
    bytes
        .try_into()
        .map_err(|_| "Seed must be exactly 32 bytes".to_string())
}

/// 32 random bytes from the operating system (Unix only).
#[cfg(unix)]
fn random_seed() -> Result<[u8; SECRET_KEY_LENGTH], String> {
    use std::io::Read;
    let mut seed = [0u8; SECRET_KEY_LENGTH];
    std::fs::File::open("/dev/urandom")
        .map_err(|e| format!("Cannot read /dev/urandom: {e}"))?
        .read_exact(&mut seed)
        .map_err(|e| format!("Cannot read /dev/urandom: {e}"))?;
    Ok(seed)
}

#[cfg(not(unix))]
fn random_seed() -> Result<[u8; SECRET_KEY_LENGTH], String> {
    Err("No operating-system random source is available in this tool on this platform. Pass --seed with 32 random bytes (for example from `openssl rand -hex 32`).".into())
}

fn rust_key_literal(key: &[u8; PUBLIC_KEY_LENGTH]) -> String {
    let mut out = String::from("[\n");
    for (index, byte) in key.iter().enumerate() {
        if index % 8 == 0 {
            out.push_str("    ");
        }
        out.push_str(&format!("0x{byte:02x}, "));
        if index % 8 == 7 {
            out.push('\n');
        }
    }
    if key.len() % 8 != 0 {
        out.push('\n');
    }
    out.push(']');
    out
}

fn now_seconds() -> Result<u64, String> {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .map_err(|_| "System clock is invalid".into())
}

fn check_field(name: &str, value: &str) -> Result<(), String> {
    if value.is_empty() || value.len() > 200 {
        return Err(format!("{name} must be 1–200 characters"));
    }
    if value.contains('\n') || value.contains('\r') {
        return Err(format!("{name} must not contain line breaks"));
    }
    Ok(())
}

fn check_fingerprint(value: &str) -> Result<String, String> {
    let fingerprint = value.trim().to_lowercase();
    if fingerprint.len() != 32 || !fingerprint.chars().all(|c| c.is_ascii_hexdigit()) {
        return Err("Fingerprint must be 32 hexadecimal characters".into());
    }
    Ok(fingerprint)
}

fn cmd_generate_key(args: &[String]) -> Result<(), String> {
    let mut seed: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--seed" => {
                seed = Some(
                    args.get(i + 1)
                        .ok_or("generate-key --seed needs a value")?
                        .clone(),
                );
                i += 2;
            }
            other => return Err(format!("Unknown generate-key option: {other}")),
        }
    }
    let seed = match seed {
        Some(text) => parse_seed(&text)?,
        None => random_seed()?,
    };
    let key = SigningKey::from_bytes(&seed);
    let public = key.verifying_key().to_bytes();
    println!("Private seed (hex) — store offline, never commit:");
    println!("{}", hex_encode(&seed));
    println!("Private seed (base64):");
    println!("{}", base64::engine::general_purpose::STANDARD.encode(seed));
    println!("Public key (hex):");
    println!("{}", hex_encode(&public));
    println!("Public key for LICENSE_PUBLIC_KEY in src-tauri/src/license.rs:");
    println!("{}", rust_key_literal(&public));
    eprintln!("WARNING: the private seed above is shown once. Store it offline now; it cannot be recovered from the public key.");
    Ok(())
}

fn cmd_issue(args: &[String]) -> Result<(), String> {
    let mut seed: Option<String> = None;
    let mut name: Option<String> = None;
    let mut email: Option<String> = None;
    let mut fingerprint: Option<String> = None;
    let mut expires = "never".to_string();
    let mut i = 0;
    while i < args.len() {
        let value = || {
            args.get(i + 1)
                .ok_or("Missing value for an issue option".to_string())
                .map(str::to_string)
        };
        match args[i].as_str() {
            "--seed" => seed = Some(value()?),
            "--name" => name = Some(value()?),
            "--email" => email = Some(value()?),
            "--fingerprint" => fingerprint = Some(value()?),
            "--expires" => expires = value()?,
            other => return Err(format!("Unknown issue option: {other}")),
        }
        i += 2;
    }
    let seed = parse_seed(&seed.ok_or("issue requires --seed")?)?;
    let name = name.ok_or("issue requires --name")?;
    let email = email.ok_or("issue requires --email")?;
    let fingerprint = check_fingerprint(&fingerprint.ok_or("issue requires --fingerprint")?)?;
    check_field("Name", &name)?;
    check_field("Email", &email)?;
    let issued_at = now_seconds()?;
    let expiry = match expires.trim() {
        "never" | "-" => "-".to_string(),
        raw => {
            let stamp: u64 = raw
                .parse()
                .map_err(|_| "--expires must be \"never\" or a Unix timestamp in seconds")?;
            if stamp <= issued_at {
                return Err("--expires must be in the future".into());
            }
            stamp.to_string()
        }
    };
    let payload =
        format!("{PAYLOAD_PREFIX}\n{name}\n{email}\n{fingerprint}\n{issued_at}\n{expiry}");
    let key = SigningKey::from_bytes(&seed);
    // The library's signing helper formats payload.signature exactly as
    // the application verifies it.
    let text = license::sign_for_test(&payload, &key);
    println!("{text}");
    eprintln!("License issued for {name} <{email}>, bound to fingerprint {fingerprint}.");
    Ok(())
}

fn cmd_verify(args: &[String]) -> Result<(), String> {
    let mut text: Option<String> = None;
    let mut fingerprint: Option<String> = None;
    let mut public_key: Option<String> = None;
    let mut i = 0;
    while i < args.len() {
        let value = || {
            args.get(i + 1)
                .ok_or("Missing value for a verify option".to_string())
                .map(str::to_string)
        };
        match args[i].as_str() {
            "--license" => text = Some(value()?),
            "--fingerprint" => fingerprint = Some(value()?),
            "--public-key" => public_key = Some(value()?),
            other => return Err(format!("Unknown verify option: {other}")),
        }
        i += 2;
    }
    let text = text.ok_or("verify requires --license")?;
    let fingerprint = check_fingerprint(&fingerprint.ok_or("verify requires --fingerprint")?)?;
    let key_bytes = hex_decode(&public_key.ok_or("verify requires --public-key")?)?;
    let key_bytes: [u8; PUBLIC_KEY_LENGTH] = key_bytes
        .try_into()
        .map_err(|_| "Public key must be exactly 32 bytes (64 hex characters)".to_string())?;
    let key = VerifyingKey::from_bytes(&key_bytes)
        .map_err(|_| "Public key is not a valid Ed25519 key".to_string())?;
    let info = license::verify_with_key(&text, &fingerprint, &key)?;
    println!("License is valid.");
    println!("Name: {}", info.name);
    println!("Email: {}", info.email);
    match info.expires_at {
        Some(stamp) => println!("Expires at (Unix seconds): {stamp}"),
        None => println!("Expires: never"),
    }
    Ok(())
}

fn usage() -> &'static str {
    "Usage: license-tool <command> [options]\n\nCommands:\n  generate-key [--seed <64 hex chars>]  Generate a vendor keypair\n  issue --seed <seed> --name <name> --email <email> --fingerprint <32 hex> [--expires never|<unix seconds>]\n  verify --license <text> --fingerprint <32 hex> --public-key <64 hex>\n  fingerprint  Print this machine's license fingerprint"
}

fn run() -> Result<(), String> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let Some(command) = args.first() else {
        return Err(usage().into());
    };
    match command.as_str() {
        "generate-key" => cmd_generate_key(&args[1..]),
        "issue" => cmd_issue(&args[1..]),
        "verify" => cmd_verify(&args[1..]),
        "fingerprint" => {
            println!("{}", license::fingerprint());
            Ok(())
        }
        "help" | "--help" | "-h" => {
            println!("{usage}");
            Ok(())
        }
        other => Err(format!("Unknown command: {other}\n\n{usage}")),
    }
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("Error: {error}");
            ExitCode::FAILURE
        }
    }
}
